        face: ['#3A3D45', '#191B1F'], lathe: '#FFFFFF', bezel: ['#565A64', '#141518'],
        knurl: '#6A6F7A', notch: '#08090B', text: '#F2F3F5', muted: '#B8BBC4', faceText: '#F2F3F5', accent: '#66B9FF', accentHalo: '#08090B',
