};

/** The turret's direction in the Prism editor. Optics and Atelier are lab-only. */
export const DEFAULT_TURRET_DIRECTION: ForgeDirectionId = 'workbench';

export const FORGE_DIRECTION_IDS: readonly ForgeDirectionId[] = ['workbench', 'optics', 'atelier'];

export function isForgeDirection(value: unknown): value is ForgeDirectionId {
  return value === 'workbench' || value === 'optics' || value === 'atelier';
}

/** Accessibility settings that change how a direction renders. */
export type ForgeRenderPrefs = Readonly<{ reduceMotion: boolean; reduceTransparency: boolean; moreContrast: boolean;
  /** Windows High Contrast and other forced palettes (web `forced-colors: active`). */
  forcedColors?: boolean }>;

/** A CSS system colour for forced-colours mode (web only). React Native Web
 * drops colour keywords it does not know, `CanvasText` and `Highlight`
 * included, but passes `var()` through; the empty custom property falls back
 * to the keyword, which the browser resolves to the user's palette. Pair it
 * with `forced-color-adjust: none` on the element. */
export type SystemColor = 'Canvas' | 'CanvasText' | 'Highlight' | 'HighlightText' | 'GrayText' | 'ButtonText' | 'LinkText';
export const systemColor = (name: SystemColor): string => `var(--forge-system-${name}, ${name})`;

/** Feedback timings shared by every direction (forge-designer-pro motion.md):
 * `press` on touch down, `endStop` the two-beat nudge at a limit, `commit`
 * the rim flash that confirms a switch. */
export const forgeFeedbackMotion = {
  press: { ms: 80, scale: 0.96 },
  endStop: { beatMs: 60, deg: 3 },
  commit: { ms: 200, peakOpacity: 0.9 },
} as const;

/** Whether the chrome may be glass right now. */
export function glassAllowed(direction: ForgeDirection, prefs: ForgeRenderPrefs): boolean {
  return direction.glass !== null && !prefs.reduceTransparency && !prefs.moreContrast;
}

/** Indicator travel for the current settings: instant under Reduce Motion. */
export function detentDurationMs(direction: ForgeDirection, prefs: ForgeRenderPrefs): number {
  return prefs.reduceMotion ? 0 : direction.motion.detentMs;
}

/** Turret geometry shared by every direction, in logical points. */
export const turretGeometry = {
  /** Outer bezel radius. */
  bezel: 66,
  /** Dial face radius. */
  face: 48,
  /** Depth of a detent slot into the bezel. */
  notch: 14,
  /** Knurl ticks around the bezel. */
  knurlCount: 72,
  /** Gap between the bezel and the near edge of each stop's name. */
  labelGap: 14,
  /** Stop name target. 44 pt tall at minimum. */
  labelWidth: 80,
  labelHeight: 44,
  /** The dial's drawing box. */
  boxWidth: 300,
  boxTop: 128,
  boxHeight: 200,
} as const;

/** Prism's four fill swatches, mirrored from `FILL_COLORS` in prism-editor.tsx
 * for the lab. Prism keeps its own copy; change both together. */
export const prismFillSwatches = [
  { name: 'violet', hex: '#6950D1' },
  { name: 'teal', hex: '#249184' },
  { name: 'amber', hex: '#E39B4C' },
  { name: 'rose', hex: '#E26D92' },
] as const;

/** Prism's editor chrome (toolbar, tool rail, layers panel, fill bar and the
 * persona popover) cut from the Workbench billet, so the panels and the dial
 * read as one material. Dark is graphite. Light is white ceramic with dark
 * engraving and a chamfer line drawn dark enough to hold its edge on the
 * light mat; it is designed for daylight, not inverted from graphite.
 * Contrast pairs are checked in forge-directions.test.ts. */
export type ForgeChrome = Readonly<{
  /** Panel face. */
  body: string;
  /** Outer chamfer line around every panel. */
  edge: string;
  /** Hairlines inside a panel: row splits, section rules. */
  rule: string;
  /** Recessed ground: unavailable controls, inputs. */
  well: string;
  /** Ground of the selected row. */
  selected: string;
  text: string;
  muted: string;
  /** Secondary text on {@linkcode ForgeChrome.selected}. */
  selectedMuted: string;
  /** Icon ink of an unavailable control in the well. */
  disabledInk: string;
  accent: string;
  /** Tint under a pressed control. */
  press: string;
  /** Hairline around a colour chip, so a chip near the body's value keeps its shape. */
  chipEdge: string;
  /** Ring around the chosen colour chip. */
  chipRing: string;
  /** Lit top edge over the panel's short shadow. */
  depth: string;
}>;

export const workbenchChrome: Readonly<Record<ForgeScheme, ForgeChrome>> = {
  dark: {
    body: '#1E2024', edge: '#3A3D44', rule: '#2E3036', well: '#141518', selected: '#2B3846',
    text: '#F2F3F5', muted: '#B8BBC4', selectedMuted: '#D5E3F0', disabledInk: '#858991', accent: '#66B9FF',
    press: '#FFFFFF14', chipEdge: '#FFFFFF59', chipRing: '#F2F3F5', depth: forgeDirections.workbench.depth.dark.panel,
  },
  light: {
    body: '#ECEDEF', edge: '#737882', rule: '#CDD0D6', well: '#DADCE1', selected: '#D3E4F4',
    text: '#1F2228', muted: '#555B66', selectedMuted: '#2F4357', disabledInk: '#6B707A', accent: '#086CB8',
    press: '#1F222814', chipEdge: '#1F222859', chipRing: '#1F2228', depth: forgeDirections.workbench.depth.light.panel,
  },
};

/** The chrome as a palette for shared controls (the Precision Scrubber). */
export function chromePalette(scheme: ForgeScheme): WorkspaceColors {
  const c = workbenchChrome[scheme];
  return { ...prismThemes[scheme], base: c.body, raised: c.body, deep: c.well, line: c.rule, text: c.text, muted: c.muted, accent: c.accent };
}

/**
 * NYC-Tron UI ships no colours; its recipes read these semantic variables
 * (docs/THEME_TOKENS.md in NYC-Tron-UI). Forge fills them from the Workbench
 * chrome so NYC-Tron parts inside an editor panel match the panel around them:
 * the list ground is the panel body, the selected row is the chrome's
 * selection, rules are the panel's rules.
 */
export function nycTronTokens(scheme: ForgeScheme): Readonly<Record<`--${string}`, string>> {
  return nycTronTokensFor(chromePalette(scheme), workbenchChrome[scheme].selected);
}

/** The same variables from any studio palette; `selected` grounds the chosen row and active controls. */
export function nycTronTokensFor(colors: WorkspaceColors, selected = colors.raised): Readonly<Record<`--${string}`, string>> {
  return {
    '--color-surface-sunken': colors.base,
    '--color-surface-raised': selected,
    '--color-border': colors.line,
    '--color-text': colors.text,
    '--color-text-muted': colors.muted,
    '--color-primary': colors.accent,
    '--color-on-primary': colors.ink,
    '--color-accent': colors.accent,
    '--color-focus': colors.accent,
    '--radius-control': `${workspaceScale.radius.control}px`,
  };
}

/** Lab backdrop: the Prism mat and an 800 x 600 artboard behind the chrome. */
export const labCanvas = {
  dark: { mat: '#18191D', paper: '#FFFEFC', paperInk: '#303440', ground: '#121316' },
  light: { mat: '#D9DBDF', paper: '#FFFEFC', paperInk: '#303440', ground: '#E4E6EA' },
} as const;

/** WCAG relative luminance of `#RRGGBB` or `#RRGGBBAA` composited over `under`. */
export function luminance(hex: string, under = '#000000'): number {
  const parse = (h: string) => {
    const v = h.replace('#', '');
    const n = (i: number) => parseInt(v.slice(i, i + 2), 16) / 255;
    return { r: n(0), g: n(2), b: n(4), a: v.length === 8 ? n(6) : 1 };
  };
  const top = parse(hex), bottom = parse(under);
  const mix = (t: number, b: number) => t * top.a + b * (1 - top.a);
  const lin = (c: number) => c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  return 0.2126 * lin(mix(top.r, bottom.r)) + 0.7152 * lin(mix(top.g, bottom.g)) + 0.0722 * lin(mix(top.b, bottom.b));
}

/** WCAG contrast ratio of two luminances. */
export function contrastRatio(a: number, b: number): number {
  const [hi, lo] = a > b ? [a, b] : [b, a];
  return (hi + 0.05) / (lo + 0.05);
}

/** The workspace palette a direction hands to shared controls (the Precision
 * Scrubber, buttons): its materials over Prism's soft and error roles. */
export function directionPalette(direction: ForgeDirection, scheme: ForgeScheme): WorkspaceColors {
  const m = direction.materials[scheme];
  const prism = prismThemes[scheme];
  return {
    ...prism,
    base: m.panelSolid, raised: m.panelSolid, deep: m.face[1],
    line: m.panelEdge.length === 9 ? prism.line : m.panelEdge, text: m.text, muted: m.muted, accent: m.accent,
  };
}

/**
 * Value-preserving tokens added on top of `theme.ts` (decisions 5, 6, 20, 21, 26, 27).
 *
 * Every entry equals the literal or the existing scale value it replaces, so
 * rewriting a component to read a token changes no pixel. Nothing here snaps a
 * value to the nearest step: a value that matches no scale step is an `off*`
 * token with the identical number.
 *
 * `theme.ts` stays the generating source. Values that already live in
 * `theme.ts`, `forge-directions.ts` or `interaction-policy.ts` are read from
 * there, not copied. The rest are literals that used to sit inside
 * components; the icon-tier literals mirror `@nitro-forge/icons` tokens.js and
 * `tokens.test.ts` fails if the two drift.
 *
 * `build-theme.mjs` turns this object into CSS through {@link cssTokens}. A CSS
 * variable is `--<group>-<key>` with the key in kebab case, and `_` between
 * digits becomes `-` (`off5_75` is `--spacing-off-5-75`).
 */
import { resolveWorkspaceScale, workspaceScale, workspaceThemes, WORKSPACE_DENSITIES, type WorkspaceDensity } from './theme';
import { forgeDirections, forgeFeedbackMotion, labCanvas, workbenchChrome, type ForgeDirectionId, type ForgeScheme } from './forge-directions';
import { forgeHitTarget, forgeMotionProfile, type ForgeMotionEvent } from './interaction-policy';

export type SchemeValue = Readonly<{ dark: string; light: string }>;
export type TokenValue = string | number | SchemeValue;
export type TokenGroup = Readonly<Record<string, TokenValue>>;

/** Values with no home in `theme.ts`: the off-scale literals found in components. */
const offScale = {
  spacing: {
    off1_5: 1.5, off2: 2, off3: 3, off5: 5, off5_75: 5.75, off6: 6, off7: 7, off10: 10, off14: 14,
    off16: 16, off18: 18, off20: 20, off22: 22, off24: 24, off25: 25, off26: 26, off28: 28, off33: 33,
    off40: 40, off48: 48, off50: 50, off76: 76, off84: 84, off96: 96, off104: 104, off360: 360,
    off480: 480, off520: 520, off600: 600, off680: 680, off760: 760, off792: 792, off800: 800, off1200: 1200,
  },
  text: { off9: 9, off11: 11, off13: 13, off15: 15, off22: 22, off28: 28 },
  leading: { off18: 18, off19: 19 },
  tracking: { offNeg0_2: -0.2, off0_4: 0.4, off1: 1 },
  radius: { off0_75: 0.75, off1: 1, off1_5: 1.5, off3: 3, off8: 8 },
  borderWidth: { off1_5: 1.5, off3: 3 },
} as const;

const standardScale = workspaceScale;

/** Colour roles Forge adds beyond NYC-Tron's scale (decision 26): Forge-local, not upstreamed. */
const forgeRoles = {
  surfaceBase: { dark: workspaceThemes.dark.base, light: workspaceThemes.light.base },
  primaryTint: { dark: workspaceThemes.dark.soft, light: workspaceThemes.light.soft },
  paper: { dark: workspaceThemes.dark.paper, light: workspaceThemes.light.paper },
  paperText: { dark: workspaceThemes.dark.paperInk, light: workspaceThemes.light.paperInk },
  paperTextMuted: { dark: workspaceThemes.dark.paperMuted, light: workspaceThemes.light.paperMuted },
} as const;

/** Icon palette, mirrored from `@nitro-forge/icons` (separate colours from the workspace: drift D1 to D4). */
const iconColour = {
  icon: { dark: '#F8FAFC', light: '#18202D' },
  iconMuted: '#737F91',
  iconSelected: '#6859E8',
  iconAccentBright: '#8E83FF',
  iconCyan: '#00B6C7',
  iconSuccess: '#139E75',
  iconWarning: '#C68B27',
  iconDanger: '#D94462',
  iconSurface: { dark: '#11131B', light: '#FFFFFF' },
} as const;

/** `stage.tsx` olive document palette (decision 27). Kept apart from `--color-paper`, which is `#FFFEFC`. Lower case, as written in `stage.tsx`. */
const stageColour = {
  stageHeading: { dark: '#eef0e9', light: '#202923' },
  stageTrack: '#222829',
  stagePaperText: '#283329',
  stagePaperTitle: '#354638',
  stageCaption: { dark: '#99a19d', light: '#556359' },
  stageGridHeadText: '#637161',
  stageClipAudio: '#637660',
  stageEmptyHint: '#798373',
  stagePaper: '#f7f5ed',
  stagePaperTextMuted: '#66735f',
  stageGridHead: '#e5e9dd',
  stageTrackBorder: '#39423f',
  stageSlideText: '#26372e',
  stageOnClip: '#ffffff',
  stageGridLine: '#dce0d5',
  stageFillFallback: '#d9b47a',
  stageTrackLabel: '#b9c7ba',
  stageQuoteRule: '#ad8551',
  stageClipVideo: '#725d7c',
  stageCellText: '#263b2b',
} as const;

const fixedColour = {
  scrim: '#000000',
  iconOnActive: '#FFFFFF',
  overlayChip: '#111827',
  onOverlayChip: '#FFFFFF',
  artboardCheckerA: '#FFFFFF',
  artboardCheckerB: '#EDEFF3',
} as const;

const camel = (text: string): string =>
  text.replace(/-([a-z0-9])/g, (_match, ch: string) => ch.toUpperCase());

const motionEvents: readonly ForgeMotionEvent[] = ['hover', 'press', 'selection', 'popover', 'panel-dock', 'detent', 'commit', 'cancel', 'error'];
const durationOf = (event: ForgeMotionEvent): number => forgeMotionProfile(event).durationMs;
const directionTurret: Readonly<Record<ForgeDirectionId, string>> = { workbench: 'snap', optics: 'reveal', atelier: 'dock' };
const directionIds = Object.keys(forgeDirections) as ForgeDirectionId[];

const schemes: readonly ForgeScheme[] = ['dark', 'light'];
const both = (read: (scheme: ForgeScheme) => string): SchemeValue => ({ dark: read('dark'), light: read('light') });
const upper = (text: string): string => text.charAt(0).toUpperCase() + text.slice(1);

/** Instrument tier: each Forge 2046 direction's materials and depth, per scheme. */
function instrumentTokens(): { color: Record<string, SchemeValue>; shadow: Record<string, SchemeValue> } {
  const color: Record<string, SchemeValue> = {};
  const shadow: Record<string, SchemeValue> = {};
  for (const id of directionIds) {
    const direction = forgeDirections[id];
    const material = (scheme: ForgeScheme) => direction.materials[scheme];
    const add = (key: string, read: (scheme: ForgeScheme) => string | undefined) => {
      if (schemes.some(scheme => !read(scheme))) return;
      color[`instrument${upper(id)}${upper(key)}`] = both(scheme => read(scheme) ?? '');
    };
    add('panel', s => material(s).panel);
    add('panelEdge', s => material(s).panelEdge);
    add('panelSolid', s => material(s).panelSolid);
    add('face0', s => material(s).face[0]);
    add('face1', s => material(s).face[1]);
    add('lathe', s => material(s).lathe);
    for (const index of [0, 1, 2, 3]) add(`bezel${index}`, s => material(s).bezel[index]);
    add('knurl', s => material(s).knurl);
    add('notch', s => material(s).notch);
    add('text', s => material(s).text);
    add('muted', s => material(s).muted);
    add('faceText', s => material(s).faceText);
    add('accent', s => material(s).accent);
    add('accentHalo', s => material(s).accentHalo);
    for (const part of ['panel', 'dial'] as const) {
      // An empty depth string means "no shadow" (Optics dial); it has no CSS value to declare.
      if (schemes.some(scheme => !direction.depth[scheme][part])) continue;
      shadow[`instrument${upper(id)}${upper(part)}`] = both(scheme => direction.depth[scheme][part]);
    }
  }
  return { color, shadow };
}

const instrument = instrumentTokens();

const chromeKeys = ['body', 'edge', 'rule', 'well', 'selected', 'text', 'muted', 'selectedMuted', 'disabledInk', 'accent', 'press', 'chipEdge', 'chipRing'] as const;
const chromeColour: Record<string, SchemeValue> = {};
for (const key of chromeKeys) chromeColour[`chrome${upper(key)}`] = both(scheme => workbenchChrome[scheme][key]);
const labKeys = ['mat', 'paper', 'paperInk', 'ground'] as const;
const labColour: Record<string, SchemeValue> = {};
for (const key of labKeys) labColour[`lab${upper(key)}`] = both(scheme => labCanvas[scheme][key]);

const turretDuration: Record<string, number> = {};
